class Solution {
public:
    int meetRequirement(int n, vector<vector<int>>& lights, vector<int>& requirement) {
        vector<int> diff(n + 1, 0);
        for (const auto& l : lights) {
            int start = max(0, l[0] - l[1]);
            int end = min(n - 1, l[0] + l[1]);
            diff[start]++;
            diff[end + 1]--;
        }
        int ans = 0, cur = 0;
        for (int i = 0; i < n; i++) {
            cur += diff[i];
            if (cur >= requirement[i]) ans++;
        }
        return ans;
    }
};

class Solution {
    public int meetRequirement(int n, int[][] lights, int[] requirement) {
        int[] diff = new int[n + 1];
        for (int[] l : lights) {
            int start = Math.max(0, l[0] - l[1]);
            int end = Math.min(n - 1, l[0] + l[1]);
            diff[start]++;
            diff[end + 1]--;
        }
        int ans = 0, cur = 0;
        for (int i = 0; i < n; i++) {
            cur += diff[i];
            if (cur >= requirement[i]) ans++;
        }
        return ans;
    }
}

/**
 * @param {number} n
 * @param {number[][]} lights
 * @param {number[]} requirement
 * @return {number}
