var meetRequirement = function(n, lights, requirement) {
    const diff = new Array(n + 1).fill(0);
    for (const [p, r] of lights) {
        const start = Math.max(0, p - r);
        const end = Math.min(n - 1, p + r);
        diff[start]++;
        diff[end + 1]--;
    }
    let ans = 0, cur = 0;
    for (let i = 0; i < n; i++) {
        cur += diff[i];
        if (cur >= requirement[i]) ans++;
    }
    return ans;
};
